let forceRefresh = false;
try { forceRefresh = $('Authenticated Collector Webhook').first().json.body?.force_refresh === true; } catch {}
if (forceRefresh) return [{ json: { force_refresh: true } }];
return $input.all();

return [
  { json: { source_name: 'European Banking Authority', source_tier: 1, language_hint: 'en', feed_url: 'https://www.eba.europa.eu/news-press/news/rss.xml' } },
  { json: { source_name: 'Bank for International Settlements', source_tier: 1, language_hint: 'en', feed_url: 'https://www.bis.org/doclist/rss_all_categories.rss' } },
  { json: { source_name: 'BIS Financial Stability Institute', source_tier: 1, language_hint: 'en', feed_url: 'https://www.bis.org/doclist/bis_fsi_publs.rss' } },
  { json: { source_name: 'European Central Bank', source_tier: 1, language_hint: 'en', feed_url: 'https://www.ecb.europa.eu/rss/press.html' } },
  { json: { source_name: 'European Central Bank Blog', source_tier: 1, language_hint: 'en', feed_url: 'https://www.ecb.europa.eu/rss/blog.html' } },
  { json: { source_name: 'European Commission Digital Strategy', source_tier: 1, language_hint: 'en', feed_url: 'https://digital-strategy.ec.europa.eu/en/rss.xml' } },
  { json: { source_name: 'BaFin', source_tier: 1, language_hint: 'de', feed_url: 'https://www.bafin.de/SiteGlobals/Functions/Solr/Suche/Ergebnisdarstellung/Expertensuche/rssnewsfeed.xml' } }
];

const sources = $('Research Sources').all().map((item) => item.json);
function sourceIndexFor(value) {
  let hostname = '';
  try { hostname = new URL(String(value || '')).hostname.toLowerCase(); } catch {}
  if (hostname.endsWith('eba.europa.eu')) return 0;
  if (hostname.endsWith('bis.org')) return 1;
  if (hostname.endsWith('ecb.europa.eu')) return 3;
  if (hostname.endsWith('digital-strategy.ec.europa.eu')) return 5;
  if (hostname.endsWith('bafin.de')) return 6;
  return 0;
}
return $input.all().map((item) => {
  const sourceIndex = sourceIndexFor(item.json.link || item.json.guid);
  return { json: item.json, pairedItem: { item: sourceIndex < sources.length ? sourceIndex : 0 } };
});

const feedItems = $input.all();
const sourceItems = $('Research Sources').all().map((item) => item.json);
const existingRows = $('Load Existing Research Keys').all().map((item) => item.json).filter((row) => row.item_key);
const existing = new Map(existingRows.map((row) => [String(row.item_key), String(row.content_hash || '')]));
const now = new Date();
const cutoff = new Date(now.getTime() - 45 * 24 * 60 * 60 * 1000);

function clean(value, max = 1800) {
  return String(value || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;|&#160;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;|&#34;/gi, String.fromCharCode(34))
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, max);
}

function canonicalUrl(value) {
  try {
    const url = new URL(String(value || ''));
    url.hash = '';
    for (const key of [...url.searchParams.keys()]) {
      if (/^(utm_|fbclid|gclid|mc_)/i.test(key)) url.searchParams.delete(key);
    }
    return url.toString().replace(/\/$/, '');
  } catch {
    return String(value || '').trim();
  }
}

function hash(value) {
  let result = 2166136261;
  for (let index = 0; index < value.length; index += 1) {
    result ^= value.charCodeAt(index);
    result = Math.imul(result, 16777619);
  }
  return (result >>> 0).toString(16).padStart(8, '0');
}

const aiPattern = /(?:\bartificial intelligence\b|\bgenerative ai\b|\bgenai\b|\bmachine learning\b|\bfoundation model(?:s)?\b|\blarge language model(?:s)?\b|\bllm(?:s)?\b|\bfrontier ai\b|\balgorithmic\b|\bkünstliche intelligenz\b|\bgenerative ki\b|\bmaschinelles lernen\b|\bki-system(?:e|en)?\b)/i;
const financePattern = /(?:\bfinanc(?:e|ial|ial-sector)\b|\bbank(?:s|ing)?\b|\bpayment(?:s)?\b|\binsurance\b|\baccounting\b|\baudit\b|\bcontroller|controlling\b|\brisk\b|\bcompliance\b|\bfraud\b|\bcredit\b|\binvestment\b|\bsupervis(?:ion|ory)\b|\bregulat(?:ion|ory)\b|\bdora\b|\bfintech\b|\bmonetary\b|\boperational resilience\b|\bfinanz(?:en|sektor|unternehmen|dienstleistung)?\b|\bbank(?:en)?\b|\bzahlung(?:en|sverkehr)?\b|\bversicherung\b|\brechnungswesen\b|\brisiko\b|\bbetrug\b|\bkredit\b|\baufsicht\b|\bregulierung\b|\bgeldwäsche\b)/i;

const candidates = [];
for (let index = 0; index < feedItems.length; index += 1) {
  const item = feedItems[index];
  if (item.json.error) continue;
  const paired = Array.isArray(item.pairedItem) ? item.pairedItem[0] : item.pairedItem;
  const sourceIndex = Number.isInteger(paired?.item) ? paired.item : 0;
  let source = sourceItems[sourceIndex] || sourceItems[0] || {};
  let sourceHost = '';
  try { sourceHost = new URL(String(item.json.link || item.json.guid || '')).hostname.toLowerCase(); } catch {}
  if (sourceHost.endsWith('eba.europa.eu')) source = sourceItems[0] || source;
  else if (sourceHost.endsWith('bis.org')) source = sourceItems[1] || source;
  else if (sourceHost.endsWith('ecb.europa.eu')) source = sourceItems[3] || source;
  else if (sourceHost.endsWith('digital-strategy.ec.europa.eu')) source = sourceItems[5] || source;
  else if (sourceHost.endsWith('bafin.de')) source = sourceItems[6] || source;
  const title = clean(item.json.title, 500);
  const description = clean(item.json.contentSnippet || item.json.summary || item.json.description || item.json.content, 1800);
  const sourceUrl = canonicalUrl(item.json.link || item.json.guid);
  if (!title || !sourceUrl) continue;
  const published = new Date(item.json.isoDate || item.json.pubDate || item.json.published || now);
  if (Number.isNaN(published.getTime()) || published < cutoff || published > new Date(now.getTime() + 24 * 60 * 60 * 1000)) continue;
  const evidence = `${title} ${description}`;
  const aiScore = aiPattern.test(evidence) ? 45 : 0;
  const financeScore = financePattern.test(evidence) ? 35 : 0;
  if (!aiScore || !financeScore) continue;
  const recencyDays = Math.max(0, (now - published) / (24 * 60 * 60 * 1000));
  const deterministicScore = Math.min(100, aiScore + financeScore + Math.max(0, 15 - recencyDays / 3) + 5);
  const itemKey = hash(sourceUrl.toLowerCase());
  const contentHash = hash(`${title.toLowerCase()}|${description.toLowerCase()}`);
  if (existing.get(itemKey) === contentHash) continue;
  candidates.push({
    item_key: itemKey,
    title,
    source_name: sourceHost.endsWith('bis.org') ? 'Bank for International Settlements' : sourceHost.endsWith('eba.europa.eu') ? 'European Banking Authority' : sourceHost.endsWith('ecb.europa.eu') ? 'European Central Bank' : sourceHost.endsWith('digital-strategy.ec.europa.eu') ? 'European Commission Digital Strategy' : sourceHost.endsWith('bafin.de') ? 'BaFin' : (source.source_name || clean(item.json.creator || item.json.source?.['_'] || 'Official source', 160)),
    source_url: sourceUrl,
    source_feed: sourceHost.endsWith('bis.org') ? 'https://www.bis.org/doclist/rss_all_categories.rss' : sourceHost.endsWith('eba.europa.eu') ? 'https://www.eba.europa.eu/news-press/news/rss.xml' : sourceHost.endsWith('ecb.europa.eu') ? 'https://www.ecb.europa.eu/rss/press.html' : sourceHost.endsWith('digital-strategy.ec.europa.eu') ? 'https://digital-strategy.ec.europa.eu/en/rss.xml' : sourceHost.endsWith('bafin.de') ? 'https://www.bafin.de/SiteGlobals/Functions/Solr/Suche/Ergebnisdarstellung/Expertensuche/rssnewsfeed.xml' : (source.feed_url || ''),
    source_tier: Number(source.source_tier || 1),
    published_at: published.toISOString(),
    language_hint: sourceHost.endsWith('bafin.de') ? 'de' : (source.language_hint || 'en'),
    description,
    deterministic_score: Math.round(deterministicScore),
    content_hash: contentHash
  });
}

candidates.sort((a, b) => b.deterministic_score - a.deterministic_score || b.published_at.localeCompare(a.published_at));
return [{ json: {
  candidates: candidates.slice(0, 20),
  candidate_count: Math.min(candidates.length, 20),
  relevant_feed_items: candidates.length,
  fetched_feed_items: feedItems.length,
  existing_research_items: existingRows.length,
  retrieved_at: now.toISOString()
} }];

const officialSources = [
  { host: 'bis.org', source_name: 'Bank for International Settlements', source_feed: 'https://www.bis.org/doclist/rss_all_categories.rss', language: 'en' },
  { host: 'eba.europa.eu', source_name: 'European Banking Authority', source_feed: 'https://www.eba.europa.eu/news-press/news/rss.xml', language: 'en' },
  { host: 'ecb.europa.eu', source_name: 'European Central Bank', source_feed: 'https://www.ecb.europa.eu/rss/press.html', language: 'en' },
  { host: 'digital-strategy.ec.europa.eu', source_name: 'European Commission Digital Strategy', source_feed: 'https://digital-strategy.ec.europa.eu/en/rss.xml', language: 'en' },
  { host: 'bafin.de', source_name: 'BaFin', source_feed: 'https://www.bafin.de/SiteGlobals/Functions/Solr/Suche/Ergebnisdarstellung/Expertensuche/rssnewsfeed.xml', language: 'de' }
];

return $input.all().map((item) => {
  if (item.json.collector_summary_only === true) return item;
  let hostname = '';
  try { hostname = new URL(String(item.json.source_url || '')).hostname.toLowerCase(); } catch {}
  const official = officialSources.find((source) => hostname === source.host || hostname.endsWith(`.${source.host}`));
  if (!official) {
    let flags = [];
    try { flags = JSON.parse(item.json.risk_flags_json || '[]'); } catch {}
    return { json: { ...item.json, risk_flags_json: JSON.stringify([...new Set([...flags, 'unrecognized_source_domain'])]) } };
  }
  return { json: { ...item.json, source_name: official.source_name, source_feed: official.source_feed, language: item.json.language || official.language } };
});

const sources = [
  { host: 'bis.org', source_name: 'Bank for International Settlements', source_feed: 'https://www.bis.org/doclist/rss_all_categories.rss', language: 'en' },
  { host: 'eba.europa.eu', source_name: 'European Banking Authority', source_feed: 'https://www.eba.europa.eu/news-press/news/rss.xml', language: 'en' },
  { host: 'ecb.europa.eu', source_name: 'European Central Bank', source_feed: 'https://www.ecb.europa.eu/rss/press.html', language: 'en' },
  { host: 'digital-strategy.ec.europa.eu', source_name: 'European Commission Digital Strategy', source_feed: 'https://digital-strategy.ec.europa.eu/en/rss.xml', language: 'en' },
  { host: 'bafin.de', source_name: 'BaFin', source_feed: 'https://www.bafin.de/SiteGlobals/Functions/Solr/Suche/Ergebnisdarstellung/Expertensuche/rssnewsfeed.xml', language: 'de' }
];
return $input.all().map((item) => {
  if (item.json.collector_summary_only === true) return item;
  const match = String(item.json.source_url || '').match(/^https?:\/\/([^\/?#]+)/i);
  const hostname = String(match?.[1] || '').toLowerCase().replace(/:\d+$/, '');
  const source = sources.find((candidate) => hostname === candidate.host || hostname.endsWith(`.${candidate.host}`));
  if (!source) return item;
  return { json: { ...item.json, source_name: source.source_name, source_feed: source.source_feed, language: item.json.language || source.language } };
});

const prepared = $('Prepare Candidate Batch').first().json;
return prepared.candidates.map((candidate) => ({ json: {
  item_key: candidate.item_key,
  eligible: false,
  last_seen_at: prepared.retrieved_at,
  content_hash: candidate.content_hash,
  analysis_method: 'pending_reassessment'
} }));

const response = { ...$json };
let content = response.choices?.[0]?.message?.content;
if (typeof content !== 'string') return [{ json: response }];
content = content.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
let parsed;
try { parsed = JSON.parse(content); } catch { return [{ json: response }]; }
let assessments = [];
if (Array.isArray(parsed)) assessments = parsed;
else if (Array.isArray(parsed?.assessments)) assessments = parsed.assessments;
else if (Array.isArray(parsed?.items)) assessments = parsed.items;
else if (Array.isArray(parsed?.results)) assessments = parsed.results;
else if (parsed?.item_key) assessments = [parsed];
else if (parsed && typeof parsed === 'object') {
  assessments = Object.entries(parsed).filter(([, value]) => value && typeof value === 'object' && !Array.isArray(value)).map(([key, value]) => ({ item_key: value.item_key || key, ...value }));
}
if (!assessments.length) return [{ json: response }];
response.choices = [{ ...response.choices[0], message: { ...response.choices[0].message, content: JSON.stringify({ assessments }) } }, ...(response.choices || []).slice(1)];
return [{ json: response }];

const prepared = $('Prepare Candidate Batch').first().json;
const originals = new Map(prepared.candidates.map((item) => [item.item_key, item]));
const now = new Date(prepared.retrieved_at);

function text(value, max) {
  return String(value || '').replace(/\s+/g, ' ').trim().slice(0, max);
}
function list(value, limit, max) {
  return Array.isArray(value) ? value.map((item) => text(item, max)).filter(Boolean).slice(0, limit) : [];
}
function parseJson(value) {
  if (typeof value !== 'string') return null;
  let content = value.trim();
  if (content.startsWith('```')) content = content.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  try { return JSON.parse(content); } catch {
    const start = content.indexOf('{');
    if (start < 0) return null;
    try { return JSON.parse(content.slice(start)); } catch { return null; }
  }
}

const parsed = parseJson($json.choices?.[0]?.message?.content);
const supplied = Array.isArray(parsed?.assessments) ? parsed.assessments : (Array.isArray(parsed?.items) ? parsed.items : []);
const byKey = new Map(supplied.filter((item) => item && item.item_key).map((item) => [String(item.item_key), item]));
const llmAvailable = byKey.size > 0;
const output = [];

for (const original of originals.values()) {
  let assessment = byKey.get(original.item_key);
  let method = 'llm';
  if (!assessment) {
    method = 'deterministic_fallback';
    assessment = {
      eligible: original.deterministic_score >= 75,
      relevance_score: original.deterministic_score,
      language: original.language_hint,
      tags: ['ai_finance', 'needs_human_review'],
      summary_de: original.description || original.title,
      summary_en: original.description || original.title,
      safe_facts: [{ fact: original.title, evidence_excerpt: original.title }],
      mission_hooks: ['Verify AI-related claims against an authoritative source before using them in finance work.'],
      confidence: 'medium',
      valid_days: 21,
      risk_flags: ['llm_assessment_unavailable']
    };
  }
  const relevance = Math.max(0, Math.min(100, Number(assessment.relevance_score ?? original.deterministic_score)));
  const confidence = ['low', 'medium', 'high'].includes(assessment.confidence) ? assessment.confidence : 'low';
  const facts = Array.isArray(assessment.safe_facts) ? assessment.safe_facts.map((fact) => ({
    fact: text(typeof fact === 'string' ? fact : fact?.fact, 700),
    evidence_excerpt: text(typeof fact === 'string' ? original.title : (fact?.evidence_excerpt || original.title), 700)
  })).filter((fact) => fact.fact && fact.evidence_excerpt).slice(0, 5) : [];
  const eligible = assessment.eligible === true && relevance >= 65 && confidence !== 'low' && facts.length > 0;
  if (!eligible) continue;
  const validDays = Math.max(7, Math.min(90, Math.round(Number(assessment.valid_days || 30))));
  const validUntil = new Date(now.getTime() + validDays * 24 * 60 * 60 * 1000);
  output.push({ json: {
    item_key: original.item_key,
    title: original.title,
    source_name: original.source_name,
    source_url: original.source_url,
    source_feed: original.source_feed,
    source_tier: original.source_tier,
    published_at: original.published_at,
    retrieved_at: prepared.retrieved_at,
    last_seen_at: prepared.retrieved_at,
    language: assessment.language === 'de' ? 'de' : 'en',
    tags_json: JSON.stringify(list(assessment.tags, 10, 80)),
    summary_de: text(assessment.summary_de || original.description || original.title, 1600),
    summary_en: text(assessment.summary_en || original.description || original.title, 1600),
    safe_facts_json: JSON.stringify(facts),
    mission_hooks_json: JSON.stringify(list(assessment.mission_hooks, 5, 300)),
    relevance_score: Math.round(relevance),
    confidence,
    valid_until: validUntil.toISOString(),
    risk_flags_json: JSON.stringify(list(assessment.risk_flags, 10, 120)),
    eligible: true,
    content_hash: original.content_hash,
    analysis_method: method
  } });
}

if (!output.length) {
  return [{ json: { collector_summary_only: true, status: 'completed', reason: 'no_eligible_candidates', llm_available: llmAvailable, fetched_feed_items: prepared.fetched_feed_items, candidate_count: prepared.candidate_count, stored_count: 0, retrieved_at: prepared.retrieved_at } }];
}
return output;

const prepared = $('Prepare Candidate Batch').first().json;
const rows = $input.all().map((item) => item.json).filter((item) => item.item_key);
return [{ json: {
  status: 'completed',
  reason: rows.length ? 'research_pool_updated' : 'no_eligible_candidates',
  fetched_feed_items: prepared.fetched_feed_items,
  relevant_feed_items: prepared.relevant_feed_items,
  candidate_count: prepared.candidate_count,
  stored_count: rows.length,
  research_item_keys: rows.map((row) => row.item_key),
  retrieved_at: prepared.retrieved_at
} }];
